export function normalizeIndexedFilePath(file) {
    if (!file.path.endsWith("/")) {
        return { normalizedPath: file.path };
    }
    const ext = file.type === "page" ? ".mdx" : ".tsx";
    return {
        normalizedPath: file.path.replace(/(?<!\/)\/+$/, "") + "/index" + ext,
        originalPath: file.path,
    };
}
export function collectParentDirectories(path) {
    const parts = path.split("/");
    const dirs = [];
    let current = "";
    for (let i = 0; i < parts.length - 1; i++) {
        const part = parts[i];
        if (!part)
            continue;
        current = current ? `${current}/${part}` : part;
        dirs.push(current);
    }
    return dirs;
}
export function stripKnownExtension(path, extensionPriority) {
    const hasExtension = extensionPriority.some((ext) => path.endsWith(ext));
    if (!hasExtension)
        return path;
    return path.replace(/\.(mdx|md|tsx|jsx|ts|js)$/, "");
}
export function resolveByExtensionPriority(fileIdx, candidateBase, extensionPriority) {
    for (const ext of extensionPriority) {
        const candidate = candidateBase + ext;
        if (fileIdx.has(candidate))
            return candidate;
    }
    return null;
}
export function resolveIndexByExtensionPriority(fileIdx, candidateBase, extensionPriority) {
    for (const ext of extensionPriority) {
        const indexPath = `${candidateBase}/index${ext}`;
        if (fileIdx.has(indexPath))
            return indexPath;
    }
    return null;
}
export function sortPathsByExtensionPriority(entries, extensionPriority) {
    return [...entries].sort((a, b) => {
        const extA = extensionPriority.findIndex((ext) => a.path.endsWith(ext));
        const extB = extensionPriority.findIndex((ext) => b.path.endsWith(ext));
        return (extA === -1 ? 99 : extA) - (extB === -1 ? 99 : extB);
    });
}
